#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~enum {  eTypeHsTrans=0,  eTypeKlapanTrans=1,  eTypePumpTrans=2,};// Структураtypedef struct : public SPROLOZ  {    //для клапана 0 - цвет при нуле, 1 - от 0 до 100, 2- при 100  COLORREF colorTrans;  COLORREF colorBkg[3];  bool bHide0Show1;  int nTypeTrans;  bool bKcaAlarm;  } Queue_TransRect;// Функция отображенияint PaintTransRect(DefinePaint)  {  QueueP(Queue_TransRect);  //  RECT rc = p->mRect;  bool bBadValue=false;  int nNumber=-1;  switch (p->nTypeTrans)  {    case eTypeHsTrans:      {        CShHS* sh = (CShHS*)PipeSh;	      if ( IsTypeOk )	      {		  if (p->bKcaAlarm)		  {			  if (( sh->mOn )||(sh->Is_State(CHs::IS_NOACK)))                nNumber = 1;			   else                nNumber = 0;		  }		  else          if (p->bHide0Show1)          {              if ( sh->mOn )                nNumber = 0;          }          else          {              if ( sh->mOn )                nNumber = 1;              else                nNumber = 0;          }	      }      }      break;    case eTypePumpTrans:      {        CShPump* sh = (CShPump*)PipeSh;	      if ( IsTypeOk )	      {          if (p->bHide0Show1)          {              if (sh->Eq_State( CPumpData::Work ))                nNumber = 0;          }          else          {              if (sh->Eq_State( CPumpData::Work ))                nNumber = 1;              else                nNumber = 0;          }	      }      }      break;    case eTypeKlapanTrans:      {        CShKlapan* sh = (CShKlapan*)PipeSh;	      if ( IsTypeOk )	      {              if (sh->Vent<=0)                nNumber = 0;              else                if (sh->Vent>=100)                  nNumber = 2;                else                  nNumber = 1;	      }      }      break;  }  if (nNumber==-1)  {     if ( ::GetMnemoStyle() & MNEMO_EDIT )     {       COLORREF clr=0x80ff;       CMyPen pen( hDC, clr );			 pen.Rect( rc );     }  }  else  {    COLORREF clrFill=p->colorBkg[nNumber];    ::TransparentRect( hDC, p->mRect, clrFill, p->colorTrans );  }  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddTransRect(DefineTegs)  {  //  AddQueueEx(Queue_TransRect);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintTransRect;  //  //  p->colorBkg[0]=0;  p->colorBkg[1]=0;  p->colorBkg[2]=0;  p->colorTrans=0;  p->nNumber=-1;  p->nTypeTrans=eTypeHsTrans;  char szHsName[64]="";  char szKlapanName[64]="";  char szPumpName[64]="";  p->bHide0Show1=false;  p->bKcaAlarm=false;  //  STegObj obj[] =    {    { 'R', "rect"   , &p->mRect  },    { 'E', "rc"     , &p->mRect  },    { 'A', "cTrans" , &p->colorTrans },	  { 'A', "cBkg0" , &p->colorBkg[0] },	  { 'A', "cBkg1" , &p->colorBkg[1] },    { 'A', "cBkg2" , &p->colorBkg[2] },	  { 'S', "hsName", szHsName, 63 },    { 'S', "klapanName", szKlapanName, 63 },    { 'S', "pumpName", szPumpName, 63 },    { 'B', "hide0show1", &p->bHide0Show1},	{ 'L', "kcalarm", &p->bKcaAlarm },    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (*szHsName)	  p->nNumber=def.AddKindPipe( id_HS    , szHsName );  else      if (*szKlapanName)      {	        p->nNumber=def.AddKind( id_Klapan   , szKlapanName );          p->nTypeTrans=eTypeKlapanTrans;      }      else          if (*szPumpName)          {	            p->nNumber=def.AddKind( id_Pump   , szPumpName );              p->nTypeTrans=eTypePumpTrans;          }  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~